package standings

import (
	"gno.land/p/nt/avl/v0"
	"gno.land/r/sys/users"
)

const maxPage = 50

// Standing is one player's place on the ladder. Rank is 1 for the highest rating and
// equal ratings share it; Rank is 0 and Rating 1000 for a player with no rated match.
// Name is the player's gno.land name, "" without one. MainClan is "" until their
// first rated match with a counted clan.
type Standing struct {
	Rank                   int
	Player, Name, MainClan string
	Rating                 int
	Wins, Losses, Draws    int
}

// ClanStanding is one clan's record across rated cross-clan matches.
type ClanStanding struct {
	Rank                int
	Clan                string
	Rating              int
	Wins, Losses, Draws int
}

// Result is one logged result. Seq is its place in the log, 1 first; Writer is the path
// of the realm that reported it. Result is "a" when the challenger won, "b" when the
// acceptor did, and "draw"; Time is the block's Unix seconds.
type Result struct {
	Seq                          int
	Writer                       string
	Challenger, Acceptor         string
	ChallengerClan, AcceptorClan string
	Result                       string
	Time                         int64
}

// Leaderboard lists rated players, highest rating first: limit of them after skipping offset.
func Leaderboard(offset, limit int) []Standing {
	checkPage(offset, limit)
	list := []Standing{}
	ladder.TraverseByOffset(offset, limit, true, true, func(n *avl.Node) bool {
		s := standingOf(address(n.Key()[2:]))
		switch {
		case len(list) == 0:
			s.Rank = rankOf(s.Rating)
		case list[len(list)-1].Rating == s.Rating:
			s.Rank = list[len(list)-1].Rank
		default:
			s.Rank = offset + len(list) + 1
		}
		list = append(list, s)
		return false
	})
	return list
}

// StandingOf returns player's standing, rated or not.
func StandingOf(player address) Standing {
	s := standingOf(player)
	if s.Wins+s.Losses+s.Draws > 0 {
		s.Rank = rankOf(s.Rating)
	}
	return s
}

// RatedPlayers counts the players on the ladder.
func RatedPlayers() int {
	return ladder.Size()
}

// ClanStandings lists every clan with a rated cross-clan match, highest rating first;
// equal ratings keep first-seen order and share a rank. Clans with no such match are left
// out: they stand at 1000 and 0-0-0.
func ClanStandings() []ClanStanding {
	list := []ClanStanding{}
	for _, c := range clans {
		if c.wins+c.losses+c.draws == 0 {
			continue
		}
		list = append(list, ClanStanding{Clan: c.name, Rating: c.rating, Wins: c.wins, Losses: c.losses, Draws: c.draws})
	}
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && list[j].Rating > list[j-1].Rating; j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
	for i := range list {
		if i > 0 && list[i].Rating == list[i-1].Rating {
			list[i].Rank = list[i-1].Rank
		} else {
			list[i].Rank = i + 1
		}
	}
	return list
}

// Results lists logged results, oldest first: limit of them after skipping offset.
func Results(offset, limit int) []Result {
	checkPage(offset, limit)
	list := []Result{}
	n := resultCount()
	if offset >= n {
		return list
	}
	end := offset + limit
	if end > n {
		end = n
	}
	for seq := offset + 1; seq <= end; seq++ {
		e := resultAt(seq)
		list = append(list, Result{
			Seq:            seq,
			Writer:         writerPaths[e.writer-1],
			Challenger:     e.challenger.String(),
			Acceptor:       e.acceptor.String(),
			ChallengerClan: clanName(e.clans[0]),
			AcceptorClan:   clanName(e.clans[1]),
			Result:         resultName(e.result),
			Time:           e.time,
		})
	}
	return list
}

// ResultCount counts the logged results.
func ResultCount() int {
	return resultCount()
}

// standingOf is player's standing without its rank.
func standingOf(player address) Standing {
	s := Standing{Player: player.String(), Name: nameOf(player), Rating: startRating}
	st := loadStanding(player)
	if st == nil {
		return s
	}
	s.MainClan = clanName(st.mainClan())
	s.Rating, s.Wins, s.Losses, s.Draws = st.rating, st.wins, st.losses, st.draws
	return s
}

// nameOf is player's gno.land name, "" when they have none.
func nameOf(player address) string {
	u := users.ResolveAddress(player)
	if u.IsDeleted() {
		return ""
	}
	return u.Name()
}

// clanName is the name of clan number n, "" for 0, no clan.
func clanName(n int) string {
	if n == 0 {
		return ""
	}
	return clans[n-1].name
}

func resultName(b byte) string {
	if b == 'd' {
		return "draw"
	}
	return string(b)
}

func checkPage(offset, limit int) {
	if offset < 0 {
		panic("offset must not be negative")
	}
	if limit < 1 || limit > maxPage {
		panic("limit must be 1 to 50")
	}
}

package standings

const (
	startRating    = 1000
	maxRating      = 0xFFFF // a ladder key holds the rating in 2 bytes
	playerK        = 32
	clanK          = 16
	maxClans       = 255    // a clan number fills one byte of a standing and a result entry
	maxPlayerCount = 0xFFFF // a player's counts are stored in 2 bytes
	maxClanCount   = 0xFFFFFFFF
)

// clanRecord is a clan's rating and its record in rated matches against other clans.
type clanRecord struct {
	name                        string
	rating, wins, losses, draws int
}

// expectedTable is the expected score, in thousandths, of a side whose opponent is rated
// 0, 25, …, 400 points above it: 1 / (1 + 10^(d / 400)), rounded.
var expectedTable = [17]int{500, 464, 429, 394, 360, 327, 297, 267, 240, 215, 192, 170, 151, 133, 118, 104, 91}

// expected is the expected score, in thousandths, of a side rated a against one rated b.
// The gap is capped at 400 points and rounded to the nearest 25.
func expected(a, b int) int {
	d := b - a
	if d < 0 {
		return 1000 - expected(b, a)
	}
	if d > 400 {
		d = 400
	}
	return expectedTable[(d+12)/25]
}

// eloChange is the change, rounded to the nearest point, of a side rated a that scored
// score thousandths (1000 a win, 500 a draw, 0 a loss) against one rated b.
func eloChange(a, b, score, k int) int {
	x := k * (score - expected(a, b))
	if x < 0 {
		return -((-x + 500) / 1000)
	}
	return (x + 500) / 1000
}

// applyChange gives a the change delta and b its negative, each kept within 0 to maxRating.
func applyChange(a, b, delta int) (int, int) {
	return clampRating(a + delta), clampRating(b - delta)
}

func clampRating(r int) int {
	if r < 0 {
		return 0
	}
	if r > maxRating {
		return maxRating
	}
	return r
}

// rate counts a match between a, playing clan number ca, and b, playing clan number cb,
// in which a scored score thousandths: in both standings, on the ladder, and in the clan
// records when both clans are counted and differ.
func rate(a, b address, ca, cb, score int) {
	sa, sb := ratedStanding(a), ratedStanding(b)
	sa.rating, sb.rating = applyChange(sa.rating, sb.rating, eloChange(sa.rating, sb.rating, score, playerK))
	sa.count(score, ca)
	sb.count(1000-score, cb)
	ladder, _ = ladder.Set(ladderKey(sa.rating, a), nil)
	ladder, _ = ladder.Set(ladderKey(sb.rating, b), nil)
	saveStanding(a, sa)
	saveStanding(b, sb)

	if ca == cb || ca == 0 || cb == 0 {
		return
	}
	x, y := &clans[ca-1], &clans[cb-1]
	x.rating, y.rating = applyChange(x.rating, y.rating, eloChange(x.rating, y.rating, score, clanK))
	tally(score, &x.wins, &x.losses, &x.draws, maxClanCount)
	tally(1000-score, &y.wins, &y.losses, &y.draws, maxClanCount)
}

// ratedStanding returns a's standing, created at startRating for a first rated match, and
// takes its key off the ladder until it is counted.
func ratedStanding(a address) *standing {
	st := loadStanding(a)
	if st == nil {
		st = &standing{rating: startRating}
	} else {
		ladder, _, _, _ = ladder.Remove(ladderKey(st.rating, a))
	}
	return st
}

// loadStanding returns a's standing, nil before their first rated match.
func loadStanding(a address) *standing {
	return decodeStanding(stringAt(&players, string(a)))
}

func saveStanding(a address, st *standing) {
	players.Set(string(a), encodeStanding(st))
}

// clanNumber is the clan number of name, its first-seen position plus one. A name not
// seen before gets the next number, or 0, no clan, once maxClans are numbered: a writer
// that fills the table must not abort another writer's endings.
func clanNumber(name string) int {
	for i, c := range clans {
		if c.name == name {
			return i + 1
		}
	}
	if len(clans) == maxClans {
		return 0
	}
	clans = append(clans, clanRecord{name: name, rating: startRating})
	return len(clans)
}

// scoreOf is the challenger's score, in thousandths, in a match that ended with result.
func scoreOf(result string) int {
	switch result {
	case "a":
		return 1000
	case "b":
		return 0
	case "draw":
		return 500
	}
	panic("unknown result")
}

// count adds a match scored score thousandths and played as clan number clan, 0 for none.
// perClan grows only as far as the clan numbers s has played.
func (s *standing) count(score, clan int) {
	tally(score, &s.wins, &s.losses, &s.draws, maxPlayerCount)
	s.lastClan = clan
	if clan == 0 {
		return
	}
	for len(s.perClan) < clan {
		s.perClan = append(s.perClan, 0)
	}
	if s.perClan[clan-1] < maxPlayerCount {
		s.perClan[clan-1]++
	}
}

// tally adds a win, loss or draw for score, each count stopping at ceiling.
func tally(score int, wins, losses, draws *int, ceiling int) {
	n := draws
	switch score {
	case 1000:
		n = wins
	case 0:
		n = losses
	}
	if *n < ceiling {
		*n++
	}
}

// mainClan is the clan number s has finished the most rated matches with, 0 for none. A
// tie goes to the last match's clan when it is one of the tied, else to first-seen order.
func (s standing) mainClan() int {
	best := 0
	for i, n := range s.perClan {
		if n > 0 && (best == 0 || n > s.perClan[best-1]) {
			best = i + 1
		}
	}
	if best != 0 && s.lastClan >= 1 && s.lastClan <= len(s.perClan) && s.perClan[s.lastClan-1] == s.perClan[best-1] {
		return s.lastClan
	}
	return best
}

// rankOf is the rank a rating holds: 1 plus the number of players rated above it.
func rankOf(rating int) int {
	i, _, _ := ladder.Get(ladderKey(rating, ""))
	return i + 1
}

// Package standings keeps Gnomepit's ratings, records, ladder and clan ratings, whatever
// arena version played the match. Only realms on its owner's writer list report results.
package standings

import (
	"chain/runtime"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
)

const (
	maxWriters  = 255 // a writer number fills one byte of a result entry
	maxClanName = 32
	maxPkgPath  = 256
)

var (
	owner       *ownable.Ownable
	writerPaths []string // every path ever a writer; its index plus one is its writer number
	writers     avl.Tree // current writer path → its writer number

	players avl.Tree     // address → standing bytes
	ladder  *avl.Node    // ladderKey of every rated player → nil
	clans   []clanRecord // in first-seen order; a clan's index plus one is its clan number
	results avl.Tree     // resultChunkKey → that chunk's result entries, oldest first
)

func init(cur realm) {
	owner = ownable.NewWithAddress(cur.Previous().Address())
	addWriter("gno.land/r/nym-gfanton001/gnomepit/arena/v0")
}

// Record rates a match the calling arena reports as ended, and logs it. result is "a" when
// the challenger won, "b" when the acceptor did, and "draw". It aborts unless the caller is
// a realm on the writer list, and on a report no correct arena sends: the same player on
// both sides, another result, or a clan name that is empty or over 32 bytes.
func Record(cur realm, challenger, acceptor address, challengerClan, acceptorClan, result string) {
	caller := cur.Previous()
	if !caller.IsCode() || !IsWriter(caller.PkgPath()) {
		panic("not a writer")
	}
	if challenger == acceptor {
		panic("same player")
	}
	score := scoreOf(result)
	if !validClan(challengerClan) || !validClan(acceptorClan) {
		panic("bad clan name")
	}
	ca, cb := clanNumber(challengerClan), clanNumber(acceptorClan)
	rate(challenger, acceptor, ca, cb, score)
	appendResult(resultEntry{writer: writers.Get(caller.PkgPath()).(int), challenger: challenger, acceptor: acceptor, clans: [2]int{ca, cb}, result: result[0], time: time.Now().Unix()})
}

// AddWriter lets the realm at pkgpath, a versioned path under gno.land/r/, report results.
// A path that was a writer before gets its old writer number back. Owner only.
func AddWriter(cur realm, pkgpath string) {
	refuseSession()
	owner.AssertOwnedBy(cur.Previous().Address())
	if !isVersionedRealm(pkgpath) {
		panic("bad writer path")
	}
	if IsWriter(pkgpath) {
		panic("already a writer")
	}
	addWriter(pkgpath)
}

// RemoveWriter stops the realm at pkgpath from reporting results. Owner only.
func RemoveWriter(cur realm, pkgpath string) {
	refuseSession()
	owner.AssertOwnedBy(cur.Previous().Address())
	if _, removed := writers.Remove(pkgpath); !removed {
		panic("not a writer")
	}
}

// TransferOwnership makes newOwner the owner. Owner only.
func TransferOwnership(cur realm, newOwner address) {
	refuseSession()
	if err := owner.TransferOwnership(0, cur, newOwner); err != nil {
		panic(err.Error())
	}
}

// refuseSession refuses a call signed with a session key, which its master may have handed
// to a page or a script: the writer list answers only to the owner's own key.
func refuseSession() {
	if _, _, _, isSession := runtime.GetSessionInfo(); isSession {
		panic("sign with the owner's own key, not a session key")
	}
}

// IsWriter reports whether the realm at pkgpath may report results.
func IsWriter(pkgpath string) bool {
	return writers.Has(pkgpath)
}

// Writers lists the realms that may report results, in writer-number order.
func Writers() []string {
	var list []string
	for _, p := range writerPaths {
		if writers.Has(p) {
			list = append(list, p)
		}
	}
	return list
}

// Owner is the address that manages the writer list.
func Owner() address {
	return owner.Owner()
}

func addWriter(pkgpath string) {
	n := 0
	for i, p := range writerPaths {
		if p == pkgpath {
			n = i + 1
			break
		}
	}
	if n == 0 {
		if len(writerPaths) == maxWriters {
			panic("too many writers")
		}
		writerPaths = append(writerPaths, pkgpath)
		n = len(writerPaths)
	}
	writers.Set(pkgpath, n)
}

// isVersionedRealm reports whether pkgpath is under gno.land/r/, at most maxPkgPath bytes of
// lowercase letters, digits and "/._-", and ends in a version element: "v" and one or more
// digits. A sub-realm path, with "#", is refused.
func isVersionedRealm(pkgpath string) bool {
	if len(pkgpath) > maxPkgPath || !strings.HasPrefix(pkgpath, "gno.land/r/") {
		return false
	}
	for _, c := range pkgpath {
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || strings.ContainsRune("/._-", c)) {
			return false
		}
	}
	v := pkgpath[strings.LastIndex(pkgpath, "/")+1:]
	if len(v) < 2 || v[0] != 'v' {
		return false
	}
	for _, c := range v[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func validClan(name string) bool {
	return len(name) >= 1 && len(name) <= maxClanName
}

func appendResult(e resultEntry) {
	key := resultChunkKey(resultCount() + 1)
	results.Set(key, stringAt(&results, key)+encodeResult(e))
}

// resultAt is logged result seq, 1 first.
func resultAt(seq int) resultEntry {
	at := (seq - 1) % resultsPerChunk * resultSize
	return decodeResult(stringAt(&results, resultChunkKey(seq))[at : at+resultSize])
}

// resultCount counts the logged results: every chunk but the last is full.
func resultCount() int {
	n := results.Size()
	if n == 0 {
		return 0
	}
	_, last := results.GetByIndex(n - 1)
	return (n-1)*resultsPerChunk + len(last.(string))/resultSize
}

// stringAt is t's string at key, "" when t has none.
func stringAt(t *avl.Tree, key string) string {
	v := t.Get(key)
	if v == nil {
		return ""
	}
	return v.(string)
}

